  static const maxResourceBytes = 256 * 1024;
  static const maxTotalBytes = 1024 * 1024;

  /// Exact local template used by the installed bundle and style.
  final String glyphTemplate;

  /// Deeply immutable resources, keyed by their canonical native request URL.
  final Map<String, List<int>> resources;

  /// Validate the one supported bundle. Caller-provided hashes grant no trust.
  factory BundledGlyphSeeds.varelaV1({
    required String glyphTemplate,
    required Map<String, List<int>> resources,
  }) {
