          input.length != entry.value.$1 ||
          input.length > maxResourceBytes ||
          (total += input.length) > maxTotalBytes) {
        throw const FormatException('Invalid bundled glyph resource size.');
      }
      final bytes = List<int>.unmodifiable(input);
      if (bytes.any((value) => value < 0 || value > 255) ||
          sha256.convert(bytes).toString() != entry.value.$2) {
        throw const FormatException('Bundled glyph integrity failure.');
      }
      checked[url] = bytes;
    }
    return BundledGlyphSeeds._(glyphTemplate, Map.unmodifiable(checked));
  }

  /// Verify the existing local style before any native resource insertion.
  void validateStyleBytes(List<int> bytes) {
    final style = jsonDecode(utf8.decode(bytes));
    if (style is! Map || style['glyphs'] != glyphTemplate) {
      throw const FormatException('Bundled glyphs do not match offline style.');
    }
  }
}

